record FeeRates(BigDecimal percent, BigDecimal minimum, BigDecimal lateSurcharge, LocalTime cutoff) {}

final class PayoutFees {
    // core: static, every input is a parameter, the result is the only output
    static BigDecimal payoutFee(BigDecimal amount, FeeRates rates, LocalTime requestedAt) {
        BigDecimal base = amount.multiply(rates.percent()).setScale(2, RoundingMode.HALF_EVEN);
        BigDecimal atLeastMinimum = base.max(rates.minimum());
        return requestedAt.isBefore(rates.cutoff())
                ? atLeastMinimum
                : atLeastMinimum.add(rates.lateSurcharge());
    }

    static String auditLine(BigDecimal amount, BigDecimal fee, LocalTime at) {
        return "payout fee " + fee + " on " + amount + " at " + at;
    }

    // shell: gather, decide, act
    static BigDecimal quotePayoutFee(BigDecimal amount, Clock clock, Audit audit) {
        FeeRates rates = FeeConfig.rates;
        LocalTime now = LocalTime.now(clock);
        BigDecimal fee = payoutFee(amount, rates, now);
        audit.write(auditLine(amount, fee, now));
        return fee;
    }
}

kotlin.src:
data class FeeRates(val percent: BigDecimal, val minimum: BigDecimal, val lateSurcharge: BigDecimal, val cutoff: LocalTime)

// core: a top-level function, every input is a parameter, the result is the only output
fun payoutFee(amount: BigDecimal, rates: FeeRates, requestedAt: LocalTime): BigDecimal {
    val base = amount.multiply(rates.percent).setScale(2, RoundingMode.HALF_EVEN)
    val atLeastMinimum = base.max(rates.minimum)
    return if (requestedAt.isBefore(rates.cutoff)) atLeastMinimum
    else atLeastMinimum + rates.lateSurcharge
}

fun auditLine(amount: BigDecimal, fee: BigDecimal, at: LocalTime) = "payout fee $fee on $amount at $at"

// shell: gather, decide, act
fun quotePayoutFee(amount: BigDecimal, clock: Clock, audit: Audit): BigDecimal {
    val rates = FeeConfig.rates
    val now = LocalTime.now(clock)
    val fee = payoutFee(amount, rates, now)
    audit.write(auditLine(amount, fee, now))
    return fee
}

