fun decideRefund(payment: Payment, now: Instant): RefundDecision = when {
    payment.status != Status.SETTLED ->
        RefundDecision.Reject(payment.id, "not settled")
    Duration.between(payment.settledAt, now) > Duration.ofDays(30) ->
        RefundDecision.Reject(payment.id, "too old")
    else -> RefundDecision.Refund(payment.id, payment.amountCents)
}

