        return new RefundDecision.Reject(payment.id(), "not settled");
    if (Duration.between(payment.settledAt(), now).compareTo(Duration.ofDays(30)) > 0)
        return new RefundDecision.Reject(payment.id(), "too old");
    return new RefundDecision.Refund(payment.id(), payment.amountCents());
}

