data class Invoice(val id: String, val dueDate: LocalDate, val paid: Boolean)

// core: pure
fun lateFee(invoice: Invoice, today: LocalDate): BigDecimal =
    if (!invoice.paid && today.isAfter(invoice.dueDate)) BigDecimal("5.00") else BigDecimal.ZERO

// shell: gather, decide, act
class LateFees(private val repo: InvoiceRepo, private val clock: Clock) {
