record Invoice(String id, LocalDate dueDate, boolean paid) {}

// core: pure
static BigDecimal lateFee(Invoice invoice, LocalDate today) {
    return !invoice.paid() && today.isAfter(invoice.dueDate()) ? new BigDecimal("5.00") : BigDecimal.ZERO;
}

